const { AsyncLocalStorage } = require('async_hooks')
const als = new AsyncLocalStorage()

// 等价于 dsh-hmr 的 runExclusive
function runExclusive(operation) {
  if (als.getStore()) return Promise.reject(new Error('HMR transactions cannot be nested'))
  return new Promise((resolve, reject) => {
    als.run(true, () => Promise.resolve().then(operation).then(resolve, reject))
  })
}

// 等价于插件的 apply()：在 start 里注册心跳
let heartbeats = 0, nested = 0
function pluginApply() {
  setInterval(() => {
    heartbeats++
    runExclusive(() => {}).catch((e) => { nested++; console.log('[plugin] 心跳内开事务失败:', e.message) })
  }, 300)
}

// cold = 冷启动（干净上下文）；hot = HMR 在事务内重启插件
if ((process.argv[2] || 'hot') === 'cold') pluginApply()
else runExclusive(pluginApply)

setTimeout(() => {
  console.log(`\n[${process.argv[2] || 'hot'}] 心跳次数=${heartbeats} 其中被「嵌套事务」拒绝=${nested}`)
  runExclusive(() => {}).then(() => console.log('事务外调用 runExclusive：成功'))
  setTimeout(() => process.exit(0), 200)
}, 1000)
实测输出
[cold] 心跳次数=3 其中被「嵌套事务」拒绝=0      ← 冷启动：正常
[cold] 事务外调用 runExclusive：成功

[plugin] 心跳内开事务失败: HMR transactions cannot be nested
